"""Logo Suricatoos (wordmark oficial) em PNG base64, para embutir nos
relatorios. Gerado a partir de logo-blue/white.svg via rsvg-convert.
LOGO_BLUE = fundo claro; LOGO_WHITE = capa/fundo escuro."""

LOGO_BLUE_B64 = ""

LOGO_WHITE_B64 = ""


import base64 as _b64
import os as _os
import tempfile as _tmp


def write_logo(dark=False):
    """Decodifica o logo e escreve num PNG temporario; devolve o caminho (ou
    None se falhar). dark=True usa a versao branca (capa/fundo escuro)."""
    data = LOGO_WHITE_B64 if dark else LOGO_BLUE_B64
    try:
        raw = _b64.b64decode(data)
        path = _os.path.join(
            _tmp.gettempdir(), "suricatoos_logo_%s.png" % ("w" if dark else "b")
        )
        with open(path, "wb") as fh:
            fh.write(raw)
        return path
    except Exception:
        return None
